"""Write the vertical clip scripts (Context/notes.md, Member 1 task 6) and the reviewer's text sheet.

Each clip: hook in the first 2 s, one idea, short plain sentences, one analogy, 15-30 s,
and a swipe teaser (intros) or a lead back to the retry question (follow-ups). Every
claim comes from the packet's source_excerpts; teaching goals and source_refs are read
from the packets, never retyped here. Run: python video/write_scripts.py
"""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
PACKETS = HERE.parent / 'learning' / 'packets'


def beats(*pairs):
    return [{'on': cue, 'do': actions.split(' ')} for cue, actions in pairs]


def card(text):
    return 'card:' + text.replace(' ', ' ')  # one action token; non-breaking spaces keep words together


