def packet(topic):
    for path in PACKETS.glob(f'{topic}.*.json'):
        return json.loads(path.read_text(encoding='utf-8'))
    raise ValueError(topic)


def main():
    sheet = ['# Vertical clip scripts for content review', '',
             'Generated by `video/write_scripts.py` from `video/scripts/*.json`. All clips are **pending review**.',
             'For each clip check: every claim against the cited lecture page, **the hook\'s claim is in the sources**,',
             'and **the analogy doesn\'t teach anything false** (Context/notes.md). Mark fixes here; Member 1 updates the',
             'script and re-renders. Clip fingerprints for `approved_version` are in each clip\'s manifest in `video/media/`.', '']
    written = 0
    for topic, clips in CLIPS.items():
        pk = packet(topic)
        sheet += [f'## {pk["label"]} (`{topic}` / `{pk["objective_id"]}`)', '']
        for variant, diagram, title, narration, stage, bts, hook, analogy, term in clips:
            v = pk['variants'][variant]
            script = {'topic_id': topic, 'objective_id': pk['objective_id'], 'variant_id': variant, 'format': 'vertical',
                      'teaching_goal': v['teaching_goal'], 'source_refs': v['source_refs'], 'review_status': 'pending',
                      'review_notes': {'hook_claim': hook, 'analogy': analogy, 'new_term': term},
                      'scenes': [{'diagram': diagram, 'title': title, 'narration': narration, 'stage': stage, 'beats': bts}]}
            (HERE / 'scripts' / f'{topic}.{variant}.json').write_text(json.dumps(script, ensure_ascii=False, indent=2) + '\n',
                                                                    encoding='utf-8')
            written += 1
            sheet += [f'### {variant}: {title}', '', f'> {narration}', '',
                      f'- Teaching goal: {v["teaching_goal"]}', f'- Sources: {", ".join(v["source_refs"])}',
                      f'- Hook claim: {hook}', f'- Analogy: {analogy}', f'- New term: {term}',
                      f'- Words: {len(narration.split())}', '']
    pilot = json.loads((HERE / 'scripts' / 'dna_replication.intro_2.json').read_text(encoding='utf-8'))
    sheet[7:7] = ['## Pilot (already rendered)', '', f'### dna_replication intro_2: {pilot["scenes"][0]["title"]}', '',
                  f'> {pilot["scenes"][0]["narration"]}', '', f'- Hook claim: {pilot["review_notes"]["hook_claim"]}',
                  f'- Analogy: {pilot["review_notes"]["analogy"]}', '']
    (HERE / 'SCRIPTS_FOR_REVIEW.md').write_text('\n'.join(sheet) + '\n', encoding='utf-8')
    print(f'wrote {written} scripts and SCRIPTS_FOR_REVIEW.md')


if __name__ == '__main__':
    main()
